import type { SeedExercise } from "./seed";

/** Source text of a generated catalogue module under src/data/generated/. */
export function serialiseCatalogueModule(
  exportName: string,
  generatorScript: string,
  catalogue: SeedExercise[],
): string {
  const json = JSON.stringify(catalogue, null, 2);
  return `import type { SeedExercise } from "../seed";

/** Generated by ${generatorScript} — do not edit by hand. */
export const ${exportName}: SeedExercise[] = ${json} as SeedExercise[];
`;
}
